Is this AXI4-Lite read response compliant?

module ro_slave (
  input             ACLK, ARESETn,
  input             ARVALID, RREADY,
  output reg        ARREADY, RVALID,
  input  [11:0]     ARADDR,
  input  [2:0]      ARPROT,
  output reg [31:0] RDATA,
  output reg [1:0]  RRESP
);
  always @(posedge ACLK or negedge ARESETn) begin
    if (!ARESETn) begin
      ARREADY <= 0; RVALID <= 0; RRESP <= 2'b00;
    end else begin
      if (ARVALID & ~ARREADY) ARREADY <= 1;
      if (ARVALID & ARREADY) begin
        RVALID <= 1;
        RDATA  <= 32'hDEADBEEF;
        RRESP  <= 2'b01;  // exclusive ok
        ARREADY <= 0;
      end
      if (RVALID & RREADY) RVALID <= 0;
    end
  end
endmodule

Please review this write-only AXI4-Lite slave:

module wo_csr_slave (
  input             ACLK,
  input             ARESETn,
  input             AWVALID,
  output reg        AWREADY,
  input  [11:0]     AWADDR,
  input  [2:0]      AWPROT,
  input             WVALID,
  output reg        WREADY,
  input  [31:0]     WDATA,
  input  [3:0]      WSTRB,
  output reg        BVALID,
  input             BREADY,
  output reg [1:0]  BRESP
);
  reg aw_done, w_done;
  reg [11:0] addr_capt;
  reg [31:0] data_capt;
  reg [3:0]  strb_capt;

  always @(posedge ACLK or negedge ARESETn) begin
    if (!ARESETn) begin
      AWREADY <= 0; WREADY <= 0; BVALID <= 0; BRESP <= 2'b00;
      aw_done <= 0; w_done <= 0;
    end else begin
      if (AWVALID & ~AWREADY & ~aw_done) AWREADY <= 1;
      if (AWVALID & AWREADY) begin
        AWREADY   <= 0;
        aw_done   <= 1;
        addr_capt <= AWADDR;
      end
      if (WVALID & ~WREADY & ~w_done) WREADY <= 1;
      if (WVALID & WREADY) begin
        WREADY    <= 0;
        w_done    <= 1;
        data_capt <= WDATA;
        strb_capt <= WSTRB;
      end
      if (aw_done & w_done & ~BVALID) begin
        BVALID <= 1;
        BRESP  <= 2'b00;
      end else if (BVALID & BREADY) begin
        BVALID  <= 0;
        aw_done <= 0;
        w_done  <= 0;
      end
    end
  end
endmodule
